// ============================================
// VALIDATION INPUT - Claude Stream With Skills
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

// --- REQUIRED: api_key ---
const apiKey = body.api_key || ctx.api_key;
if (!apiKey || typeof apiKey !== 'string') {
  errors.push('api_key requis');
}

// --- REQUIRED: model ---
const model = body.model || ctx.model || 'claude-sonnet-4-20250514';

// --- REQUIRED: messages ---
const messages = body.messages || ctx.messages;
if (!messages || !Array.isArray(messages) || messages.length === 0) {
  errors.push('messages requis');
}

// --- REQUIRED: container with skills ---
const container = body.container || ctx.container;
if (!container || !container.skills || container.skills.length === 0) {
  errors.push('container.skills requis');
}

// --- REQUIRED: callback_url ---
const callbackUrl = body.callback_url || ctx.callback_url;
if (!callbackUrl || typeof callbackUrl !== 'string') {
  errors.push('callback_url requis');
}

// --- REQUIRED: correlation_id ---
const correlationId = body.correlation_id || ctx.correlation_id;
if (!correlationId || typeof correlationId !== 'string') {
  errors.push('correlation_id requis');
}

// --- Optional ---
const betas = body.betas || ctx.betas || ['files-api-2025-04-14'];
const system = body.system || ctx.system || null;
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 16000);
const tools = body.tools || ctx.tools || [];
const metadata = body.metadata || ctx.metadata || {};

const streamConfig = {
  flush_timeout_ms: body.stream_config?.flush_timeout_ms || 500,
  flush_token_count: body.stream_config?.flush_token_count || 20,
  flush_size_bytes: body.stream_config?.flush_size_bytes || 4096
};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    correlation_id: correlationId,
    metadata: metadata
  };
}

return {
  valid: true,
  api_key: apiKey.trim(),
  model: model,
  betas: betas,
  system: system,
  messages: messages,
  max_tokens: maxTokens,
  container: container,
  tools: tools,
  callback_url: callbackUrl,
  correlation_id: correlationId,
  stream_config: streamConfig,
  metadata: metadata,
  startTime: Date.now()
};

const input = $input.first().json;

return {
  success: false,
  status: 'error',
  correlation_id: input.correlation_id,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  metadata: input.metadata
};

// ============================================
// PREPARE STREAM REQUEST
// ============================================

const data = $json;

return {
  immediate_response: {
    success: true,
    status: 'streaming',
    correlation_id: data.correlation_id,
    message: 'Stream with skills initiated. Packets will be sent to callback_url.'
  },
  stream_request: data
};

