// ============================================
// PROCESS RESPONSE & EXTRACT FILES
// ============================================

const input = $input.first().json;
const prevData = $('Prepare Stream').first().json;
const req = prevData.stream_request;
const startTime = req.startTime || Date.now();
const latencyMs = Date.now() - startTime;

// Extract text content
let textContent = '';
const fileRefs = [];

if (input.content) {
  for (const block of input.content) {
    if (block.type === 'text') {
      textContent += block.text;
    }
    // Check for file artifacts
    if (block.type === 'tool_result' && block.output?.file_id) {
      fileRefs.push({
        file_id: block.output.file_id,
        name: block.output.name || 'document',
        mime_type: block.output.mime_type
      });
    }
  }
}

// Check container_result for files
if (input.container_result?.files) {
  for (const file of input.container_result.files) {
    fileRefs.push({
      file_id: file.file_id,
      name: file.name,
      mime_type: file.mime_type
    });
  }
}

// Build final packet with files
const finalPacket = {
  correlation_id: req.correlation_id,
  sequence: 1,
  events: [
    { type: 'content_block_delta', delta: { text: textContent } },
    { type: 'message_stop' }
  ],
  final: true,
  cumulative_tokens: (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0),
  usage: input.usage || { input_tokens: 0, output_tokens: 0 },
  provider: 'anthropic',
  model: req.model,
  duration_ms: latencyMs,
  timestamp: new Date().toISOString(),
  metadata: req.metadata,
  // Files are included in final packet for Skills (Contract §3.4 compliant)
  files: fileRefs.map(f => ({
    file_id: f.file_id,
    filename: f.name,           // Aligned: name → filename
    mime_type: f.mime_type,
    size_bytes: f.size || 0,    // Aligned: add size_bytes
    download_url: `https://api.anthropic.com/v1/files/${f.file_id}/content`
  }))
};

return {
  callback_url: req.callback_url,
  packet: finalPacket,
  api_key: req.api_key
};
